<?php
session_start();if(empty($_SESSION['user_id'])){header('Location:/pages/login.php');exit;}require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/order_reservations.php';$userId=(int)$_SESSION['user_id'];wanawanExpirePendingOrders($pdo,$userId);$orderIds=array_values(array_unique(array_map('intval',$_SESSION['checkout_batch_order_ids']??[])));if(!$orderIds){header('Location:/pages/orders.php');exit;}$marks=implode(',',array_fill(0,count($orderIds),'?'));
function batchSellerUsers(PDO $pdo,string $type,int $sellerId):array{if($type==='user')return[$sellerId];if(!in_array($type,['publisher','shop'],true))return[];$table=$type==='publisher'?'publisher_staff':'shop_staff';$column=$type==='publisher'?'publisher_id':'shop_id';$q=$pdo->prepare("SELECT user_id FROM $table WHERE $column=?");$q->execute([$sellerId]);return array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));}
$enableReservationCountdown=true;$reservationState=$pdo->prepare("SELECT COUNT(*) total,SUM(payment_status='pending') pending_count,MIN(UNIX_TIMESTAMP(reservation_expires_at)) deadline FROM orders WHERE user_id=? AND order_id IN ($marks)");$reservationState->execute(array_merge([$userId],$orderIds));$reservationState=$reservationState->fetch(PDO::FETCH_ASSOC);$reservationCountdownDeadline=(int)($reservationState['deadline']??0);$reservationCountdownExpired=(int)($reservationState['pending_count']??0)!==(int)($reservationState['total']??0);if($reservationCountdownExpired&&$_SERVER['REQUEST_METHOD']==='POST'){header('Location:/pages/orders.php?tab=cancelled&expired=1');exit;}
$pdo->exec("SET SESSION sql_mode=(SELECT REPLACE(@@SESSION.sql_mode,'ONLY_FULL_GROUP_BY',''))");
$orderStmt=$pdo->prepare("SELECT o.*,COALESCE(p.company_name,s.shop_name,NULLIF(u.display_name,''),u.email,'ผู้ขายวนวรรณ') seller_name,b.seller_type,b.seller_id FROM orders o JOIN order_items oi ON oi.order_id=o.order_id JOIN books b ON b.book_id=oi.book_id LEFT JOIN publishers p ON b.seller_type='publisher' AND p.publisher_id=b.seller_id LEFT JOIN shops s ON b.seller_type='shop' AND s.shop_id=b.seller_id LEFT JOIN users u ON b.seller_type='user' AND u.user_id=b.seller_id WHERE o.user_id=? AND o.order_id IN ($marks) GROUP BY o.order_id ORDER BY o.order_id");$orderStmt->execute(array_merge([$userId],$orderIds));$orders=$orderStmt->fetchAll(PDO::FETCH_ASSOC);if(count($orders)!==count($orderIds)){http_response_code(403);exit('ไม่พบชุดคำสั่งซื้อ');}
$paymentError='';if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['confirm_payment'])){$slip=null;if(!empty($_FILES['payment_slip']['name'])&&$_FILES['payment_slip']['error']===UPLOAD_ERR_OK){$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['payment_slip']['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png'][$mime]??null;if($ext&&$_FILES['payment_slip']['size']<=5*1024*1024){$dir=__DIR__.'/uploads/payment_slips';if(!is_dir($dir))mkdir($dir,0775,true);$file='slip_batch_'.bin2hex(random_bytes(10)).'.'.$ext;move_uploaded_file($_FILES['payment_slip']['tmp_name'],$dir.'/'.$file);$slip='uploads/payment_slips/'.$file;}}
if(!$slip)$paymentError='กรุณาแนบสลิป JPEG หรือ PNG ขนาดไม่เกิน 5 MB';else{$pdo->beginTransaction();try{$update=$pdo->prepare("UPDATE orders SET payment_status='reviewing',payment_slip_url=? WHERE order_id=? AND user_id=? AND payment_status='pending'");foreach($orders as $order){$update->execute([$slip,$order['order_id'],$userId]);$itemQ=$pdo->prepare('SELECT oi.book_id FROM order_items oi WHERE oi.order_id=?');$itemQ->execute([$order['order_id']]);foreach($itemQ->fetchAll(PDO::FETCH_COLUMN) as $bookId)$pdo->prepare('DELETE FROM cart_items WHERE user_id=? AND book_id=?')->execute([$userId,$bookId]);}
$saStmt=$pdo->query("SELECT user_id FROM users WHERE role='super_admin'");
foreach($saStmt->fetchAll(PDO::FETCH_COLUMN) as $sa) wanawanNotifyUser($pdo, (int)$sa, 'มีสลิปคำสั่งซื้อใหม่ (Batch)', 'ผู้ซื้อแนบสลิปสำหรับชุดคำสั่งซื้อ รอการตรวจสอบ', 'order');
wanawanNotifyUser($pdo, $userId, 'แจ้งชำระเงินเรียบร้อย', 'แนบสลิปสำหรับ '.count($orders).' ร้านแล้ว กำลังรอผู้ดูแลระบบตรวจสอบ', 'order');$pdo->commit();unset($_SESSION['checkout_selected_ids'],$_SESSION['checkout_batch_order_ids']);header('Location:/pages/orders.php?tab=pending');exit;}catch(Throwable $e){$pdo->rollBack();throw$e;}}}
$total=array_sum(array_column($orders,'total_amount'));

// สร้าง QR Code PromptPay สำหรับยอดรวมทั้งหมด
$promptpayPayload = generatePromptPayPayload(WANAWAN_PROMPTPAY_ID, (float)$total);
// ส่งไป QuickChart เพื่อทำเป็นรูปภาพ
$qr = 'https://quickchart.io/qr?size=300&margin=2&ecLevel=M&text=' . rawurlencode($promptpayPayload);
?>
<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ชำระเงินหลายร้าน - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css?v=<?= filemtime(__DIR__.'/../assets/css/styles.css') ?>"><style>*{box-sizing:border-box}.wrap{max-width:1080px;margin:auto;padding:44px 32px 85px}.title{color:var(--secondary-color);font-size:30px;margin-bottom:20px}.layout{display:grid;grid-template-columns:1fr 380px;gap:25px;align-items:start}.card{border:1px solid #e1dcd7;border-radius:15px;padding:25px;background:#fff;box-shadow:0 4px 15px rgba(0,0,0,0.03)}.card h2{margin-top:0;font-size:18px;color:var(--secondary-color);margin-bottom:15px}.qr{text-align:center;padding:22px;background:#faf8f6;border-radius:12px}.qr img{width:260px;max-width:100%}.amount{font-size:35px;color:var(--secondary-color);font-weight:700;margin:10px 0}.order{padding:14px 0;border-bottom:1px solid #eee}.order strong,.row{display:flex;justify-content:space-between;gap:12px}.order span{font-size:13px;color:var(--text-muted)}.row{margin:17px 0}.total{font-size:21px;color:var(--secondary-color);font-weight:700;border-top:1px solid #ddd;padding-top:18px}.btn-pay-later{display:block;width:100%;height:54px;line-height:54px;border:1px solid #ccc;border-radius:10px;background:#fff;color:var(--text-dark);font-weight:700;text-align:center;text-decoration:none;margin-top:20px;transition:background .2s}.btn-pay-later:hover{background:#f9f9f9}.error{padding:12px;background:#fde7e3;color:#a33;border-radius:9px;margin-bottom:15px}.btn-upload{margin-top:15px;width:100%;height:54px;background:var(--secondary-color);color:#fff;border:none;border-radius:10px;font-size:16px;font-weight:700;cursor:pointer;transition:all 0.2s}.btn-upload:hover{background:#3a4b41}.file-input{margin-top:15px;width:100%;padding:10px;border:2px dashed #d1c9c5;border-radius:10px;background:#fff;color:var(--text-muted);font-size:14px;cursor:pointer}@media(max-width:780px){.wrap{padding:20px 15px 60px}.title{font-size:24px;margin-bottom:15px}.layout{grid-template-columns:1fr;gap:15px}.card{padding:18px;border-radius:12px}.qr{padding:15px}.qr img{width:220px}.amount{font-size:28px}.total{font-size:18px}.btn-pay-later,.btn-upload{height:48px;line-height:48px;font-size:15px}}</style></head><body><?php require __DIR__.'/../components/header.php';?><main class="wrap"><h1 class="title">ชำระเงินรวม <?=count($orders)?> ร้าน</h1><?php if($paymentError):?><div class="error"><?=htmlspecialchars($paymentError)?></div><?php endif;?><div class="layout"><section class="card"><div class="qr"><img src="<?=htmlspecialchars($qr)?>" alt="QR Code"><div class="amount">฿<?=number_format($total,2)?></div>
<form method="POST" enctype="multipart/form-data">
    <h3 style="color:var(--secondary-color);margin:10px 0 5px;">แนบสลิปการโอนเงิน</h3>
    <p style="color:var(--text-muted);font-size:14px;margin-bottom:0;">กรุณาโอนเงินตามยอดด้านบนและแนบสลิปเพื่อยืนยัน</p>
    <input type="file" name="payment_slip" id="payment-slip-input" class="file-input" accept="image/jpeg, image/png" required>
